// Helpers shared by the src/io test executables (test_io.cpp, test_io_load.cpp).
#pragma once

#include <gtest/gtest.h>
#include <unistd.h>

#include <cstddef>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <nlohmann/json.hpp>
#include <string>
#include <utility>
#include <vector>

#include "hsolve/error.hpp"

namespace hs::io_test {

/// Directory of the committed fixtures (generated by tests/data/make_io_fixtures.py).
inline std::filesystem::path fixture_dir() {
  return std::filesystem::path(HSOLVE_TEST_DATA_DIR) / "io";
}

inline std::filesystem::path fixture(const std::string& name) { return fixture_dir() / name; }

inline const nlohmann::json& expected() {
  static const nlohmann::json j = [] {
    std::ifstream in(fixture("expected.json"));
    if (!in) throw std::runtime_error("cannot open tests/data/io/expected.json");
    return nlohmann::json::parse(in);
  }();
  return j;
}

inline std::vector<char> read_bytes(const std::filesystem::path& p) {
  std::ifstream in(p, std::ios::binary);
  if (!in) throw std::runtime_error("cannot open " + p.string());
  return {std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
}

inline void write_bytes(const std::filesystem::path& p, const std::vector<char>& bytes) {
  std::ofstream out(p, std::ios::binary | std::ios::trunc);
  out.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
  if (!out) throw std::runtime_error("cannot write " + p.string());
}

inline void write_text(const std::filesystem::path& p, const std::string& text) {
  write_bytes(p, std::vector<char>(text.begin(), text.end()));
}

struct ThrownError {
  std::string code = "none";  ///< hs::to_string of the error code, or "none"
  std::string message;
};

/// The hs::Error thrown by f, if any.
template <class F>
ThrownError error_of(F&& f) {
  try {
    f();
  } catch (const hs::Error& e) {
    return {hs::to_string(e.code()), e.what()};
  }
  return {};
}

/// hs::to_string of the error code thrown by f, or "none".
template <class F>
std::string error_code_of(F&& f) {
  return error_of(std::forward<F>(f)).code;
}

/// Checks an expected.json error case: {"error": code, "message": optional substring}.
template <class F>
void expect_error(const nlohmann::json& c, F&& f) {
  const ThrownError e = error_of(std::forward<F>(f));
  EXPECT_EQ(e.code, c["error"].get<std::string>()) << e.message;
  if (c.contains("message")) {
    EXPECT_NE(e.message.find(c["message"].get<std::string>()), std::string::npos)
        << "message: " << e.message;
  }
}

/// Per-test scratch directory under the system temp dir, removed afterwards.
class TempDirTest : public ::testing::Test {
 protected:
  void SetUp() override {
    const auto* info = ::testing::UnitTest::GetInstance()->current_test_info();
    std::string leaf = "hsolve_io_" + std::to_string(::getpid()) + "_" + info->test_suite_name() +
                       "_" + info->name();
    for (char& c : leaf)
      if (c == '/') c = '_';  // typed suites are named "Suite/0"
    dir_ = std::filesystem::temp_directory_path() / leaf;
    std::filesystem::remove_all(dir_);
    std::filesystem::create_directories(dir_);
  }
  void TearDown() override { std::filesystem::remove_all(dir_); }
  std::filesystem::path tmp(const std::string& name) const { return dir_ / name; }

 private:
  std::filesystem::path dir_;
};

}  // namespace hs::io_test
